// NOMAD D010 Concepts — scratch kernel cross-check harness. Appended to NOMAD_D010_Concepts.fs for test_feature
// only; NEVER written to Onshape. Reports through a deliberate regenError (test_feature returns notices only).

// BEGIN GENERATED D010 EXPECTED
// Generated by CAD/tools/d010_phase2_study.py --emit (python expectations for the kernel check).
const D010_EXPECT_CG = [
        ["cgAmax", "A", { "phi" : 125, "sR" : 1, "tR" : 75, "sL" : 1, "tL" : 75, "psi" : 0, "stay" : false }, [-7.1892, 200.4951, 66.6333]],
        ["cgB1stay", "B1", { "phi" : 110, "sR" : 0, "tR" : 0, "sL" : 0, "tL" : 0, "psi" : 110, "stay" : true }, [-6.1195, 214.148, 87.0055]],
        ["cgB1normal", "B1", { "phi" : 110, "sR" : 0, "tR" : 0, "sL" : 0, "tL" : 0, "psi" : 65, "stay" : false }, [-6.1195, 206.4892, 73.5685]]
    ];
const D010_EXPECT_GAP = { "plugA120" : 1.2, "plugB125" : 2.072, "leafCore45" : 1.1411 };
// END GENERATED D010 EXPECTED

annotation { "Feature Type Name" : "D010 Check" }
export const d010Check = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
    }
    {
        throw regenError(d010CheckMsg(context, id));
    }, {});

// Kernel checks vs the python expectations (also called by the gallery harness, NOMAD_D010_Concepts.gallery.test.fs).
function d010CheckMsg(context is Context, id is Id) returns string
{
        const o = { "cables" : true, "cg" : true, "env" : true, "internals" : true, "wm" : true };
        var msg = "D010CHK";
        // CG: kernel-side evaluation of the same lumped-mass list vs python
        var worstCg = 0;
        for (var i = 0; i < size(D010_EXPECT_CG); i += 1)
        {
            const e = D010_EXPECT_CG[i];
            const cc = d010CG(e[1], e[2]) / millimeter;
            worstCg = max(worstCg, max(abs(cc[0] - e[3][0]), max(abs(cc[1] - e[3][1]), abs(cc[2] - e[3][2]))));
        }
        msg = msg ~ " cgErr " ~ roundToPrecision(worstCg, 5);
        // A lid vs rear plug keep-out at 120 (python +1.2)
        const a = d010Instance(context, id + "a", "A", { "phi" : 120, "sR" : 1, "tR" : 75, "sL" : 1, "tL" : 75, "psi" : 0, "stay" : false },
            vector(0, 0, 0) * millimeter, "CHK", -1, o);
        const dA = evDistance(context, { "side0" : a["lidShell"], "side1" : a["KEEPOUT_PLUGS_MAIN"] }).distance / millimeter;
        msg = msg ~ " plugA120 " ~ roundToPrecision(dA, 3) ~ "/" ~ roundToPrecision(D010_EXPECT_GAP.plugA120, 3);
        const dCas = evDistance(context, { "side0" : a["casR"], "side1" : a["lidShell"] }).distance / millimeter;
        const dBr = evDistance(context, { "side0" : a["bracketR"], "side1" : a["lidShell"] }).distance / millimeter;
        msg = msg ~ " casLid " ~ roundToPrecision(dCas, 2) ~ " brLid " ~ roundToPrecision(dBr, 2);
        // B1 stack vs plug keep-out at 125 (python +2.1): nearest of lid core / leaf frame
        const b = d010Instance(context, id + "b", "B1", { "phi" : 125, "sR" : 0, "tR" : 0, "sL" : 0, "tL" : 0, "psi" : 0, "stay" : false },
            vector(1000, 0, 0) * millimeter, "CHK", -1, o);
        const dB = min(evDistance(context, { "side0" : b["lidShell"], "side1" : b["KEEPOUT_PLUGS_MAIN"] }).distance,
                evDistance(context, { "side0" : qUnion([b["leafR"], b["leafL"]]), "side1" : b["KEEPOUT_PLUGS_MAIN"] }).distance) / millimeter;
        const wb = evBox3d(context, { "topology" : b["wm"] });
        msg = msg ~ " wmBox " ~ roundToPrecision((wb.maxCorner[0] - wb.minCorner[0]) / millimeter, 1) ~ "x" ~
            roundToPrecision(norm(wb.maxCorner - wb.minCorner) / millimeter, 1) ~ " wmN " ~ size(evaluateQuery(context, b["wm"])) ~
            " wmLeaf " ~ roundToPrecision(evDistance(context, { "side0" : b["wm"], "side1" : qUnion([b["leafR"], b["leafL"]]) }).distance / millimeter, 2) ~
            " padCtl " ~ roundToPrecision(evDistance(context, { "side0" : b["wmPad"], "side1" : b["ctl"] }).distance / millimeter, 2) ~
            " skin " ~ roundToPrecision(evDistance(context, { "side0" : b["wm"], "side1" : qCreatedBy(id + "b" + "B" + "wm" + "pad", EntityType.FACE) }).distance / millimeter, 2) ~
            " padCab " ~ roundToPrecision(evDistance(context, { "side0" : b["wmPad"], "side1" : qCreatedBy(id + "b" + "cB", EntityType.BODY) }).distance / millimeter, 2) ~
            " inlCab " ~ roundToPrecision(evDistance(context, { "side0" : b["wm"], "side1" : qCreatedBy(id + "b" + "cB", EntityType.BODY) }).distance / millimeter, 2);
        msg = msg ~ " plugB125 " ~ roundToPrecision(dB, 3) ~ "/" ~ roundToPrecision(D010_EXPECT_GAP.plugB125, 3);
        // B1 leaf vs lid core at psi 45 (python convex hull incl. relief chamfer; kernel frame is a subset -> >=)
        const c = d010Instance(context, id + "c", "B1", { "phi" : 110, "sR" : 0, "tR" : 0, "sL" : 0, "tL" : 0, "psi" : 45, "stay" : true },
            vector(2000, 0, 0) * millimeter, "CHK", -1, o);
        const dL = evDistance(context, { "side0" : qUnion([c["leafR"], c["leafL"]]), "side1" : c["lidShell"] }).distance / millimeter;
        msg = msg ~ " leafCore45 " ~ roundToPrecision(dL, 3) ~ "/" ~ roundToPrecision(D010_EXPECT_GAP.leafCore45, 3);
        const dS = evDistance(context, { "side0" : c["stayR"], "side1" : c["base"] }).distance / millimeter;
        msg = msg ~ " stayBase " ~ roundToPrecision(dS, 2);
        const nb = size(evaluateQuery(context, qCreatedBy(id, EntityType.BODY)));
        msg = msg ~ " bodies " ~ nb;
        return msg;
}
